class Queue {
    constructor() {
        this.items = {};
        this.head = 0;
        this.tail = 0;
    }
    enqueue(element) {
        this.items[this.tail++] = element;
    }
    dequeue() {
        if (this.head === this.tail) return undefined;
        const item = this.items[this.head];
        delete this.items[this.head++];
        return item;
    }
    size() { return this.tail - this.head; }
}

