    // Reverse linked list pointers
}

exercises.solutionCode:
const reverseLinkedList = (head) => {
    let prev = null;
    let curr = head;

    while (curr !== null) {
        const nextTemp = curr.next; // Save next node reference
        curr.next = prev;           // Reverse pointer direction
        prev = curr;                // Advance prev pointer
        curr = nextTemp;            // Advance curr pointer
    }
    return prev; // New head of reversed list
};

