class TreeNode {
    constructor(val) {
        this.val = val;
        this.left = null;
        this.right = null;
    }
}

class BST {
    constructor() {
        this.root = null;
    }
    insert(val) {
        const newNode = new TreeNode(val);
        if (!this.root) { this.root = newNode; return; }
        let curr = this.root;
        while (true) {
            if (val < curr.val) {
                if (!curr.left) { curr.left = newNode; break; }
                curr = curr.left;
            } else {
                if (!curr.right) { curr.right = newNode; break; }
                curr = curr.right;
            }
        }
    }
}

