    // Implement DFS Graph Traversal
}

exercises.solutionCode:
const dfsGraph = (startNode, graph) => {
    const visited = new Set();
    const result = [];

    const dfs = (node) => {
        if (!node || visited.has(node)) return;
        visited.add(node);
        result.push(node);

        const neighbors = graph.get(node) || [];
        for (const neighbor of neighbors) {
            dfs(neighbor);
        }
    };

    dfs(startNode);
    return result;
};

