class TrieNode {
    constructor() {
        this.children = {};
        this.isWord = false;
    }
}

class Trie {
    constructor() {
        this.root = new TrieNode();
    }
    insert(word) {
        let curr = this.root;
        for (let char of word) {
            if (!curr.children[char]) curr.children[char] = new TrieNode();
            curr = curr.children[char];
        }
        curr.isWord = true;
    }
    startsWith(prefix) {
        let curr = this.root;
        for (let char of prefix) {
            if (!curr.children[char]) return false;
            curr = curr.children[char];
        }
        return true;
    }
}

