class AlgorithmEngine {
    static generateSortingSteps(array) {
        const arr = [...array];
        const steps = [];
        const n = arr.length;

        for (let i = 0; i < n - 1; i++) {
            for (let j = 0; j < n - 1 - i; j++) {
                steps.push({ type: 'compare', indices: [j, j + 1], state: [...arr] });
                if (arr[j] > arr[j + 1]) {
                    [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];
                    steps.push({ type: 'swap', indices: [j, j + 1], state: [...arr] });
                }
            }
        }
        return steps;
    }

    static benchmarkAlgorithm(fn, ...args) {
        const start = performance.now();
        const result = fn(...args);
        const duration = performance.now() - start;
        return { result, durationMs: duration.toFixed(4) };
    }
}

const steps = AlgorithmEngine.generateSortingSteps([5, 3, 8, 1]);
console.log(`Generated ${steps.length} sorting visualization steps.`);

const bench = AlgorithmEngine.benchmarkAlgorithm(() => [1, 2, 3].map(x => x * 2));
console.log(`Benchmark Duration: ${bench.durationMs}ms`);
